export type EffectCost=
 | {kind:'ko-character';scope:'own-character';amount:number;trait?:string;optional:boolean}
 | {kind:'trash';scope:'hand'|'self'|'deck';amount:number;all?:boolean;requiresTrigger?:boolean;color?:string;trait?:string;cardType?:Card['type'];maxCost?:number;minPower?:number;exactPower?:number;optional:boolean}
